/**
 * Technology logo outlines.
 *
 * Extracted once from the `simple-icons` package (CC0) and committed here,
 * rather than carrying a 23 MB dependency to use these paths. Each entry is a
 * single SVG path on a 24x24 grid plus the official brand colour, which the
 * tiles use on hover.
 *
 * To add a logo: `npm i --no-save simple-icons`, read `title`, `hex` and
 * `path` off the matching `si<Name>` export, paste an entry here, then
 * uninstall. The package is not needed at build or run time.
 *
 * DELIBERATELY ABSENT: AWS, Azure, Canva, Adobe XD/Illustrator/Photoshop and
 * OpenAI. simple-icons removed them all over trademark policy. Technologies
 * without an entry here render as a lettermark tile instead, so they still
 * appear in the grid — see TechTile in TechnologiesSection.tsx.
 */

export interface TechLogo {
  title: string;
  /** Official brand colour, used on hover only. */
  hex: string;
  /** SVG path data on a 24x24 viewBox. */
  path: string;
}

