/**
 * Full-colour logos.
 *
 * These seven brands have no single-path monochrome mark available:
 * simple-icons removed Adobe, Canva, AWS, Azure and OpenAI over trademark
 * policy. Their marks are taken instead from the CC0 `logos` set (Gil
 * Barbara) and `devicon`, which carry them as multi-path, multi-colour SVG.
 *
 * They render through a different path in TechTile — an inline SVG body
 * rather than a single filled path — which is why they are a separate
 * registry rather than extra fields on TechLogo. The hero icon cloud draws
 * with canvas Path2D and can only use single-path marks, so it consumes
 * TECH_LOGOS only and is unaffected by anything here.
 *
 * Gradient and clip ids are namespaced per logo at extraction time, so two
 * of these can never collide in one document.
 */
export interface TechColorLogo {
  title: string;
  /** Dominant brand colour, for tinting adjacent UI. */
  hex: string;
  viewBox: string;
  /** Inner SVG markup, already carrying its own fills. */
  body: string;
}

